python3 -c "
import json
with open('/app/resources/treasury_bulletin_1974_12.json', 'r') as f:
    data = json.load(f)

# Search for Export-Import or Direct Sales related items
def search(obj, keys=['EXPORT-IMPORT', 'EXIM', 'DIRECT SALES', 'EXPORT IMPORT'], path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            found = any(key.lower() in k.lower() for key in keys)
            if found:
                results.append((path + '.' + k if path else k, v))
            results.extend(search(v, keys, path + '.' + k if path else k))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(search(item, keys, f'{path}[{i}]'))
    return results

results = search(data)
for r in results[:50]:
    print(r)
"
